contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single test function driving c. We take params: depositor's deposit value and an unlockTime.
    // The test requires this contract to have enough balance to send `amount`.
    function runTest(uint amount, uint unlockTime) public {
        // need some positive deposit amount
        require(amount > 0);
        // ensure this contract has enough ETH to forward; caller must fund this contract beforehand
        require(address(this).balance >= amount);

        // Call Put on c forwarding `amount` wei. This should succeed on original P even if amount < MinSum.
        c.Put{value: amount}(unlockTime);

        // After Put, the stored balance for address(this) must be at least `amount` (i.e., the deposit increased the stored balance).
        // Observe via public getter Acc(address).balance -> c.Acc returns a tuple (unlockTime,balance) because Acc is public mapping to struct.
        // The autogenerated getter for a public mapping to a struct returns the struct members; we read the second value (balance).
        (, uint storedBalance) = c.Acc(address(this));

        // The general rule: storedBalance is >= amount
        assert(storedBalance >= amount);
    }

    // allow this test contract to receive ETH so it can forward deposits
    receive() external payable {}
}

