pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: depositor address and deposit amount and collect amount and unlockTime
    // We let the fuzzer find values that expose the mutant which rejects small deposits (< MinSum)
    function testFuzz_property(address actor, uint256 depositAmt, uint256 collectAmt, uint256 unlockTime) public {
        // Keep actor non-zero
        vm.assume(actor != address(0));
        // Keep depositAmt reasonably bounded to avoid overflow issues in the test harness
        depositAmt = bound(depositAmt, 0, 5 ether);
        collectAmt = bound(collectAmt, 0, 5 ether);
        // Ensure unlockTime is not absurdly large; allow past/present/future
        unlockTime = bound(unlockTime, 0, block.timestamp + 100000);

        // The distinguishing behavior involves small deposits that are below MinSum (1 ether)
        // We do NOT restrict them away; let the fuzzer supply depositAmt < MinSum sometimes.

        // Fund the actor for making the deposit
        vm.deal(actor, depositAmt + 1 ether);
        // Actor makes a deposit via Put (public payable) through prank
        vm.prank(actor);
        // use try/catch to capture reverts (mutant will revert on small deposits)
        bool putOk;
        try c.Put{value: depositAmt}(unlockTime) {
            putOk = true;
        } catch {
            putOk = false;
        }

        // Record balance as seen by the contract (Acc mapping getter provides Holder struct via public mapping)
        // The auto-generated getter for Acc returns (unlockTime, balance)
        (uint accUnlockP, uint accBalP) = c.Acc(actor);

        // Now attempt to Collect some amount (may succeed or silently do nothing depending on conditions)
        // Ensure actor has enough gas/funds for potential receives; set prank for actor
        vm.prank(actor);
        bool collectOk;
        try c.Collect(collectAmt) {
            collectOk = true;
        } catch {
            collectOk = false;
        }

        // After Collect, read the mapping again
        (uint accUnlockAfter, uint accBalAfter) = c.Acc(actor);

        // GENERAL RULE to assert: If the initial Put call succeeded in the reference, then after Collect the recorded balance is never less than zero and specifically
        // for the reference contract a Put of any non-negative msg.value (including below MinSum) that succeeded will result in accBalAfter >= accBalP - collectAmt bounded by underflow protections.
        // But the mutant will have rejected small deposits (putOk == false) for depositAmt < MinSum, causing accBalP to be unchanged in reference but the mutant to have different behavior.

        // We assert a universal observable property on the reference contract:
        // If Put succeeded (putOk == true) then the balance recorded immediately after Put equals accBalP, and after Collect the balance is either unchanged or decreased by at most collectAmt.
        // This is expressed as: accBalAfter + collectAmt >= accBalP
        // (covers both unchanged and successful collection of up to collectAmt). This reads only c's public getters.

        // Single assertion required by the harness: it must hold for the reference under all inputs and be violated by the mutant for some inputs.
        assertTrue(accBalAfter + collectAmt >= accBalP);
    }
}

