pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address depositor, uint256 depositAmount, uint256 withdrawAmount, uint256 unlockOffset) public {
        // keep wide but sensible bounds
        depositAmount = bound(depositAmount, 0, 5 ether);
        withdrawAmount = bound(withdrawAmount, 0, 5 ether);
        unlockOffset = bound(unlockOffset, 0, 1 days);
        // ensure depositor has funds
        vm.deal(depositor, depositAmount + 1 ether);

        // depositor sends deposit by invoking fallback which calls Put(0)
        vm.prank(depositor);
        // send depositAmount wei to contract via fallback
        (bool sent,) = address(c).call{value: depositAmount}("");
        // record whether deposit transaction succeeded
        bool depositSucceeded = sent;

        // compute recorded balance before collect
        uint256 before = c.Acc(depositor).balance;

        // if deposit succeeded then before should have increased accordingly in reference
        // Now attempt to Collect from depositor: we need the caller to be depositor
        // Ensure unlockTime has passed by setting unlock time earlier using Put via direct call if deposit succeeded
        // If depositSucceeded is false, we still call Collect to observe behavior
        // Advance time so Collect's block.timestamp>unlockTime if unlockOffset small
        vm.warp(block.timestamp + unlockOffset + 1);

        vm.prank(depositor);
        bool collectOk;
        try c.Collect(withdrawAmount) {
            collectOk = true;
        } catch {
            collectOk = false;
        }

        // After Collect, the invariant for the reference contract: if depositSucceeded and collect withdrew up to the recorded balance,
        // then the recorded balance should be zero when withdrawAmount >= before and collect succeeded.
        // Express that rule as a single assertion over c's public getter.
        if (depositSucceeded && collectOk && withdrawAmount >= before) {
            // Then recorded balance must be zero
            assertTrue(c.Acc(depositor).balance == 0);
        } else {
            // If the antecedent is false, the universal property makes no claim; assert true to keep single assert form
            // We still require a single assertTrue reading c: use a tautology involving c (balance >= 0)
            assertTrue(c.Acc(depositor).balance >= 0);
        }
    }
}

