        vm.startPrank(caller);
        bool ok;
        try c.Put{value: amount}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The universal property: if the call succeeded, the recorded unlockTime for caller is at least block.timestamp
        // (reference contract clamps to now). We assert that when the Put call returned successfully, c.Acc(caller).unlockTime >= block.timestamp
        // Read via public getter Acc
        if (ok) {
            (, uint storedBalance) = c.Acc(caller);
            // ensure deposit took effect to confirm this is the intended stateful Put (balance>0 implies Put updated storage)
            // single assertion required: check unlockTime >= block.timestamp via the Acc getter
            (uint storedUnlock, ) = (c.Acc(caller).unlockTime, storedBalance); // workaround to fetch unlockTime then balance
            // However direct tuple deconstruction of mapping struct getter isn't available; use the autogenerated getter which returns (uint unlockTime, uint balance)
            (uint u, uint b) = c.Acc(caller);
            assertTrue(u >= block.timestamp);
        } else {
            // if Put reverted, we still must make one assertion about c's visible state; in this branch Put reverted so no state change
