import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: actor (address) and unlockTime (uint256) and value (uint256)
    function testFuzz_property(address actor, uint256 unlockTime, uint256 value) public {
        // Keep actor non-zero
        vm.assume(actor != address(0));
        // bound value to a reasonable range so vm.deal can fund the actor
        uint256 val = bound(value, 0, 5 ether);
        // The invariant concerns block.timestamp at the time of Put. We will call Put at the current timestamp.
        // Fund the actor and perform the call as that actor
        vm.deal(actor, val);
        vm.startPrank(actor);
        // call Put with fuzzed unlockTime and fuzzed value
        // If the reference contract is used, after the call Acc[actor].unlockTime >= block.timestamp
        // We capture the success of the call (some mutants or situations could revert)
        try c.Put{value: val}(unlockTime) {
            // call succeeded
        } catch {
            // call reverted; still allowed — the property we assert is about the stored unlockTime when the call completes.
        }
        vm.stopPrank();

        // Single universal assertion: after Put returns (or reverts), reading the public mapping Acc gives the stored unlockTime.
        // The reference ensures that if the Put completed (i.e., did not revert) then Acc[actor].unlockTime >= block.timestamp.
        // To keep the assertion valid for the reference on ALL admissible inputs, restrict to the case where the Put succeeded.
        // We re-call a zero-value Put to observe success without changing state if needed; instead, we detect success by
        // reading the stored unlockTime and checking it against block.timestamp — for the reference this holds whenever Put succeeded.

        // Read stored unlockTime
        (uint256 storedUnlockTime, uint256 storedBalance) = getHolder(actor);

        // If the last Put call sent value > 0, the call could have reverted if require failed; only assert when call likely succeeded:
        // We assert that storedUnlockTime >= block.timestamp. This is the single assertTrue required.
        assertTrue(storedUnlockTime >= block.timestamp);
    }

    // Helper to read the public struct via autogenerated getter. The mapping is public in C, which exposes Acc(address) => (unlockTime, balance)
    function getHolder(address a) internal view returns (uint256 unlockTime, uint256 balance) {
        // The compiler creates a getter named Acc that returns (uint,uint). Call it on c.
        return c.Acc(a);
    }
}

