pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: actor address, priorUnlock, newUnlock, depositAmount
    function testFuzz_property(address actor, uint256 priorUnlock, uint256 newUnlock, uint256 depositAmount) public {
        // Keep actor non-zero and depositAmount > 0 (we need to send value so Put executes its logic)
        vm.assume(actor != address(0));
        depositAmount = bound(depositAmount, 1, 10 ether);

        // we want priorUnlock to be strictly less than newUnlock to observe an increase
        // keep a wide bound but enforce strictness
        priorUnlock = bound(priorUnlock, 0, type(uint32).max);
        newUnlock = bound(newUnlock, priorUnlock + 1, uint256(type(uint32).max) + 1);

        // Fund the actor so it can send ETH
        vm.deal(actor, depositAmount);

        // First, set up the prior state: we need Acc[actor].unlockTime = priorUnlock.
        // Achieve this by calling Put via actor with a crafted _unlockTime = priorUnlock and some value.
        vm.prank(actor);
        c.Put{value: depositAmount}(priorUnlock);

        // Sanity: ensure the prior unlockTime is indeed <= priorUnlock (should hold for reference)
        // Now call Put again with a larger newUnlock; send a positive value to trigger balance change
        vm.prank(actor);
        c.Put{value: depositAmount}(newUnlock);

        // The intended universal property for the correct contract:
        // After calling Put with newUnlock > priorUnlock and sending value, Acc[actor].unlockTime >= newUnlock or >= block.timestamp
        // Read the observable public getter Acc(actor).unlockTime via the auto-generated getter.
        (uint256 observedUnlock,,) = readAcc(actor);

        // Because block.timestamp may be greater than newUnlock in some rare fuzz cases, accept either.
        // The property is: observedUnlock >= newUnlock || observedUnlock >= block.timestamp
        // We assert that at least one holds. This will be true for the reference for all admissible inputs,
        // and will be false for the mutant when it fails to update unlockTime (observedUnlock remains priorUnlock < newUnlock).
        assertTrue(observedUnlock >= newUnlock || observedUnlock >= block.timestamp);
    }

    // helper to call the public getter Acc(address) which returns (unlockTime, balance)
    function readAcc(address a) internal view returns (uint256, uint256, bytes32) {
        // The compiler-generated getter for mapping (address => Holder) public Acc;
        // returns (uint unlockTime, uint balance). But solidity ABI packs only those two.
        // To keep the signature stable we call the getter via low-level staticcall and decode manually.
        (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("Acc(address)", a));
        require(ok, "getter failed");
        // decode as (uint256,uint256)
        (uint256 u, uint256 b) = abi.decode(ret, (uint256, uint256));
        return (u, b, bytes32(0));
    }
}

