    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 sendAmt, uint256 unlockTime) public {
        // Keep actor as a valid address (non-zero) and bind sendAmt to realistic range
        vm.assume(actor != address(0));
        sendAmt = bound(sendAmt, 0, 10 ether);
        // Ensure actor has funds to send
        vm.deal(actor, sendAmt + 1 ether);

        // Read prior unlockTime for the actor
        uint priorUnlock = c.Acc(actor).unlockTime;

        // Perform the Put as actor, sending sendAmt wei
        vm.prank(actor);
        c.Put{value: sendAmt}(unlockTime);

        // After Put, the reference contract guarantees unlockTime >= block.timestamp
        // and in particular not less than priorUnlock unless block.timestamp decreased (it cannot),
        // so assert that new unlockTime is >= priorUnlock and >= block.timestamp
        uint newUnlock = c.Acc(actor).unlockTime;

        // Single assertion reading c's public getter: the reference always sets unlockTime to at least block.timestamp
        // This will fail on the mutant that omits updating unlockTime for some inputs.
        assertTrue(newUnlock >= block.timestamp);
    }
}

