contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: deposit some ether for this contract's address, set unlockTime to T,
    // then attempt to Collect amount at time == T and observe that the transfer did NOT happen.
    // Parameters:
    //  - depositAmount: how much wei to put into c for this tester
    //  - collectAmount: how much wei to try to withdraw (<= depositAmount)
    //  - unlockTime: epoch seconds to set as unlockTime (must be >= block.timestamp)
    // Note: caller must ensure this contract has enough balance to send depositAmount.
    function runTest(uint depositAmount, uint collectAmount, uint unlockTime) public payable {
        // preconditions for meaningful test
        require(depositAmount >= collectAmount, "deposit must cover collect");

        // fund this contract if needed (caller must send msg.value)
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");

        // make a deposit into C for this contract's address, setting unlockTime
        c.Put{value: depositAmount}(unlockTime);

        // read stored balance before attempted collect
        (uint beforeBalance) = (c.Acc(address(this)).balance);

        // attempt to collect exactly at unlockTime: verifier can schedule this call at block.timestamp == unlockTime
        // The Collect call is state-changing and must be a top-level call
        c.Collect(collectAmount);

        // read stored balance after attempted collect
        (uint afterBalance) = (c.Acc(address(this)).balance);

        // Rule: when collect is attempted at timestamp == unlockTime, balance must not decrease (withdrawal disallowed)
        // This holds on original P (uses >) but is violated by mutant M (uses >=).
        assert(afterBalance >= beforeBalance);
    }

    // allow the contract to receive funds so caller can fund it before calling runTest
    receive() external payable {}
}

