contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: depositor address, deposit amount, withdraw amount, and a timestamp warp
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 withdrawAmt, uint64 warpTo) public {
        // keep addresses and amounts in wide but sensible ranges
        vm.assume(depositor != address(0));
        depositAmt = bound(depositAmt, 1 wei, 10 ether);
        withdrawAmt = bound(withdrawAmt, 1 wei, 10 ether);
        // MinSum in contract is 1 ether; to exercise the path require deposit >= MinSum
        // ensure depositAmt is at least MinSum so Collect path can be considered
        if (depositAmt < 1 ether) depositAmt = 1 ether;

        // fund depositor and perform Put via fallback (or Put) so Acc[depositor] is set
        vm.deal(depositor, depositAmt);
        vm.prank(depositor);
        // call Put with unlockTime exactly equal to the chosen warpTo time
        // cast warpTo to uint since Put takes uint
        c.Put{value: depositAmt}(uint256(warpTo));

        // warp to exactly the unlock time
        vm.warp(uint256(warpTo));

        // try to Collect withdrawAmt from depositor while msg.sender is depositor
        bool ok;
        vm.prank(depositor);
        try c.Collect{value: 0}(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assert): On the reference, Collect must be disallowed when block.timestamp == unlockTime,
        // so ok == false for this scenario when withdrawAmt <= balance and balance >= MinSum.
        // The mutant allowing >= would make ok == true for some inputs; thus this assertion will fail on the mutant.
        assertTrue(!ok);
    }
}

