pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: actor address, deposit amount, withdraw amount, unlockOffset
    // unlockOffset is seconds added to current block.timestamp to set unlockTime
    function testFuzz_property(address actor, uint256 deposit, uint256 withdraw, uint64 unlockOffset) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // bound deposit and withdraw to reasonable ranges
        deposit = bound(deposit, 1, 10 ether);
        withdraw = bound(withdraw, 0, 10 ether);
        // keep unlockOffset small so warp stays reasonable
        unlockOffset = uint64(bound(unlockOffset, 0, 1000));

        // We need deposit >= MinSum (1 ether) to allow Collect path
        // Ensure deposit >= 1 ether
        if (deposit < 1 ether) deposit = 1 ether;

        // Put funds into contract via fallback/Put by making a payable call
        vm.deal(actor, deposit);
        vm.prank(actor);
        // fallback calls Put(0) which sets unlockTime to block.timestamp; instead call Put with desired unlock
        // Call Put directly to set unlockTime in the future: using unlock = block.timestamp + unlockOffset
        uint unlock = block.timestamp + unlockOffset;
        vm.prank(actor);
        // call Put by invoking fallback with calldata for Put; simpler: call Put via low-level call to itself
        // But C has public Put, so call it directly
        // Need to compile-time know C interface; use vm.prank to send
        // send deposit and call Put
        vm.prank(actor);
        c.Put{value: deposit}(unlock);

        // Now warp to exactly unlock time
        vm.warp(unlock);

        // Ensure withdraw amount is <= deposit so mutant may allow collect
        withdraw = bound(withdraw, 0, deposit);

        // Do the Collect call as the actor and catch whether it succeeded
        bool ok;
        vm.prank(actor);
        try c.Collect(withdraw) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract requires block.timestamp > acc.unlockTime (strict), so at block.timestamp == unlock
        // Collect must NOT succeed. Therefore assertTrue(!ok).
        // This is the single assertion: holds for reference for ALL admissible inputs; mutant (>=) allows success for some inputs.
        assertTrue(!ok);
    }
}

