pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters:
    // - depositor: the address that will put funds and later try to collect
    // - depositAmt: amount to deposit (in wei)
    // - withdrawAmt: amount to attempt to collect
    // - unlockOffset: offset (in seconds) from current block.timestamp to set as unlockTime
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 withdrawAmt, uint64 unlockOffset) public {
        // Keep deposit in a reasonable range and non-zero so MinSum (1 ether) applies in the logic
        depositAmt = bound(depositAmt, 1 ether, 5 ether);
        // withdraw amount between 0 and depositAmt
        withdrawAmt = bound(withdrawAmt, 0, depositAmt);
        // unlockOffset: allow zero to produce unlockTime == block.timestamp
        unlockOffset = uint64(bound(unlockOffset, 0, 1000));

        // ensure depositor is a funded EOA
        vm.deal(depositor, depositAmt + 1 ether);

        // depositor calls Put with unlock time = block.timestamp + unlockOffset
        vm.prank(depositor);
        c.Put{value: depositAmt}(block.timestamp + unlockOffset);

        // Now warp to exactly block.timestamp + unlockOffset (the boundary case)
        vm.warp(block.timestamp + unlockOffset);

        // Attempt to Collect withdrawAmt from depositor; capture whether it succeeded
        bool ok;
        vm.prank(depositor);
        try c.Collect(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): On the reference contract, Collect must NOT succeed when called at exactly unlockTime.
        // Therefore, ok must be false whenever the current block.timestamp equals the stored unlockTime for depositor.
        // Read the stored unlockTime to ensure we're checking the boundary case only when equal.
        uint storedUnlock = c.Acc(depositor).unlockTime();

        // Only assert the property when we are exactly at the stored unlockTime; otherwise the reference makes no claim here.
        if (block.timestamp == storedUnlock) {
            // Reference C requires block.timestamp > unlockTime for Collect to run; so at equality it must refuse => ok == false
            assertTrue(!ok);
        } else {
            // If not at the boundary, we don't assert anything (property is about the exact-equality boundary)
            assertTrue(true);
        }
    }
}

