contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: depositor (address) and amount and unlock offset
    // We will: deposit funds via Put with unlockTime = block.timestamp + offset
    // then warp to exactly that unlockTime and attempt Collect(amount).
    // The reference requires block.timestamp > unlockTime, so when timestamp == unlockTime Collect must fail.
    function testFuzz_property(address depositor, uint96 amount, uint64 offset) public {
        vm.assume(depositor != address(0));
        // keep amount in a reasonable range and non-zero
        uint256 am = bound(uint256(amount), 1, 5 ether);
        // offset bounded to a small range so warp is practical (including 0)
        uint256 off = uint256(bound(uint64(offset), 0, 1000));

        // fund depositor
        vm.deal(depositor, am + 1 ether);

        // make depositor call Put with unlockTime = block.timestamp + off
        vm.prank(depositor);
        c.Put{value: am}(block.timestamp + off);

        // ensure mapping stored balance >= MinSum and >= am
        // MinSum is 1 ether in contract; ensure we deposited >= MinSum
        // If our fuzzed am was less than MinSum, top-up so deposit >= MinSum
        if (am < 1 ether) {
            uint256 top = 1 ether - am;
            vm.deal(depositor, top);
            vm.prank(depositor);
            c.Put{value: top}(block.timestamp + off);
            am = am + top;
