        // warp to exactly the stored unlockTime
        vm.warp(block.timestamp + off);

        // attempt Collect(am) as depositor and observe whether it succeeded
        bool ok;
        vm.prank(depositor);
        try c.Collect(am) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL ASSERTION: reference C must NOT allow Collect to succeed at timestamp == unlockTime
        // i.e., ok must be false for all inputs under the reference. The mutant (>=) will make ok==true for some inputs.
        assertTrue(!ok);
    }
