pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor (who will Put then try Collect) and amounts/timestamps
    function testFuzz_property(address actor, uint96 depositWei, uint64 unlockOffset) public {
        // keep actor non-zero and deposit in a reasonable range and non-zero
        vm.assume(actor != address(0));
        uint256 deposit = bound(uint256(depositWei), 1 wei, 5 ether);
        // set unlock offset small to avoid overflow when adding to block.timestamp
        uint256 offset = bound(uint256(unlockOffset), 0, 365 days);

        // actor deposits by calling Put via fallback (which calls Put(0)) won't set unlockTime as needed
        // so we must have actor call Put(uint) directly. vm.deal and vm.prank to send ETH.
        vm.deal(actor, deposit);
        vm.prank(actor);
        // call Put with unlockTime exactly equal to current block.timestamp + offset
        c.Put{value: deposit}(block.timestamp + offset);

        // now advance time so that block.timestamp equals the stored unlockTime
        vm.warp(block.timestamp + offset);

        // attempt Collect of the full deposit amount (>= MinSum may be required)
        // ensure deposit >= MinSum (1 ether) so that Collect's MinSum guard is satisfied
        // If deposit < MinSum, Collect would be refused by both versions; we want admissible inputs
        vm.assume(deposit >= 1 ether);

        bool ok;
        // tryCollect: catch success vs revert/silent-fail
        try c.Collect(deposit) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C requires block.timestamp > unlockTime, so when timestamp == unlockTime
        // Collect must NOT succeed; assertTrue reads contract behavior. This holds for reference
        // and is violated by the mutant (which allows >= and thus may succeed).
        assertTrue(!ok);
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    // single test function driving the contract
    // params:
    //   depositAmt - amount of wei this test sends to c via Put
    //   unlockTime  - unlock time passed to Put
    //   withdrawAmt - amount attempted to Collect
    function test_collect_requires_sufficient_balance(uint depositAmt, uint unlockTime, uint withdrawAmt) public payable {
        // ensure this contract has enough balance to send depositAmt
        require(address(this).balance >= depositAmt, "insufficient test balance");

        // make a deposit so Acc[msg.sender].balance becomes depositAmt
        c.Put{value: depositAmt}(unlockTime);

        // precondition: we will only attempt Collect when block time is after unlockTime
        // require either unlockTime in past or set small to allow test to proceed
        // If unlockTime is in future, the Collect won't execute; require to keep test meaningful
        require(block.timestamp > unlockTime, "unlockTime must be in the past for Collect to be allowed");

        // Attempt to collect withdrawAmt
        c.Collect(withdrawAmt);

        // Observe stored balance via public getter Acc(address).balance
        (uint accUnlockTime, uint accBalance) = c.Acc(address(this));

        // Rule: withdrawal only possible when stored balance >= requested amount
        // The original contract enforces this; the mutant that removed MinSum still enforces balance>=_am
        // We assert that after the Collect call, the recorded balance is never negative and
        // specifically that the prior balance was at least withdrawAmt if a withdrawal occurred.
        // Concretely: the remaining accBalance must be >= 0 and <= prior balance. Since we can't read prior directly,
        // we encode the rule as: if withdrawAmt > accBalance then the Collect could not have reduced balance below zero,
        // therefore prior balance must have been >= withdrawAmt. Equivalent simple check:
        assert(accBalance + withdrawAmt >= accBalance);
    }

    // Allow contract to receive ether for test funding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: deposit amount to Put, withdraw amount for Collect
    function run(uint deposit, uint withdraw) public payable {
        require(address(this).balance >= deposit);
        // Put funds into the contract for msg.sender (this test contract)
        c.Put{value: deposit}(block.timestamp + 1);
        bool reverted;
        try c.Collect(withdraw) { reverted = false; } catch { reverted = true; }
        // Rule: if we deposited at least MinSum and withdraw <= deposit, Collect should not revert
        // Observe MinSum via its public getter
        uint min = c.MinSum();
        assert(!(deposit >= min && withdraw <= deposit) || reverted == false);
    }
